query:
CREATE TABLE `emailVerificationTokens` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`token` varchar(255) NOT NULL,
	`expiresAt` timestamp NOT NULL,
	`used` int NOT NULL DEFAULT 0,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `emailVerificationTokens_id` PRIMARY KEY(`id`),
	CONSTRAINT `emailVerificationTokens_token_unique` UNIQUE(`token`)
);
CREATE TABLE `passwordResetTokens` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`token` varchar(255) NOT NULL,
	`expiresAt` timestamp NOT NULL,
	`used` int NOT NULL DEFAULT 0,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `passwordResetTokens_id` PRIMARY KEY(`id`),
	CONSTRAINT `passwordResetTokens_token_unique` UNIQUE(`token`)
);
CREATE TABLE `sessions` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`token` varchar(255) NOT NULL,
	`expiresAt` timestamp NOT NULL,
	`userAgent` text,
	`ipAddress` varchar(45),
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `sessions_id` PRIMARY KEY(`id`),
	CONSTRAINT `sessions_token_unique` UNIQUE(`token`)
);
ALTER TABLE `users` MODIFY COLUMN `openId` varchar(64);
ALTER TABLE `users` MODIFY COLUMN `email` varchar(320) NOT NULL;
ALTER TABLE `users` MODIFY COLUMN `loginMethod` varchar(64) NOT NULL DEFAULT 'email';
ALTER TABLE `users` MODIFY COLUMN `lastSignedIn` timestamp;
ALTER TABLE `users` ADD `username` varchar(100);
ALTER TABLE `users` ADD `passwordHash` text;
ALTER TABLE `users` ADD `emailVerified` int DEFAULT 0 NOT NULL;
ALTER TABLE `users` ADD `isActive` int DEFAULT 1 NOT NULL;
ALTER TABLE `users` ADD CONSTRAINT `users_username_unique` UNIQUE(`username`);
ALTER TABLE `users` ADD CONSTRAINT `users_email_unique` UNIQUE(`email`);

